package handler

import "github.com/glauth/glauth/v2/pkg/config"

// ExpandIncludeGroups returns the transitive closure of the groups reached by
// following IncludeGroups from each gid in seeds. Every seed gid is part of the
// result, so callers can use it to answer "which groups does this membership
// effectively belong to".
//
// The walk is cycle safe: a group already visited is never expanded again, so
// cyclic or diamond-shaped inheritance cannot recurse forever or duplicate
// entries.
func ExpandIncludeGroups(groups []config.Group, seeds []int) []int {
	includes := make(map[int][]int, len(groups))
	for _, group := range groups {
		includes[group.GIDNumber] = group.IncludeGroups
	}

	visited := make(map[int]bool)
	var walk func(gid int)
	walk = func(gid int) {
		if visited[gid] {
			return
		}
		visited[gid] = true
		for _, included := range includes[gid] {
			walk(included)
		}
	}
	for _, seed := range seeds {
		walk(seed)
	}

	result := make([]int, 0, len(visited))
	for gid := range visited {
		result = append(result, gid)
	}
	return result
}

