		Tracer(trace.NewNoopTracerProvider().Tracer("test")),
	}
}

const sampleFileData = `{
  "groups": [
    {"name": "svc", "gidnumber": 5501},
    {"name": "engineers", "gidnumber": 5502, "includegroups": [5501]},
    {"name": "everyone", "gidnumber": 5503, "includegroups": [5502]}
  ],
  "users": [
